function placeholder(name){return `<section class="view"><div class="empty-preview">${sample}<b style="margin-top:20px">${name}</b><p>این صفحه در محدوده prototype مرحله صفر طراحی تفصیلی نشده است.</p><a class="btn primary" href="#today">بازگشت به کارهای روز</a></div></section>`}

const routes={today,opportunities,opportunity,product,company,documents:()=>placeholder('صف اسناد'),reports:()=>placeholder('گزارش‌ها'),settings:()=>placeholder('تنظیمات')};
function render(){const page=(location.hash||'#today').slice(1).split('?')[0];app.innerHTML=(routes[page]||today)();document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===page||(page==='opportunity'&&a.dataset.nav==='opportunities')));document.querySelector('#sidebar').classList.remove('open');app.focus();bindPage()}
function bindPage(){const search=document.querySelector('#opSearch');if(search)search.addEventListener('input',e=>{const q=e.target.value.trim();document.querySelectorAll('[data-filter-row]').forEach(r=>r.hidden=!r.dataset.filterRow.includes(q))});document.querySelectorAll('[data-case-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-case-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelector('#caseContent').innerHTML=caseTab(b.dataset.caseTab)}));document.querySelectorAll('[data-case-jump]').forEach(b=>b.addEventListener('click',()=>{const tab=document.querySelector(`[data-case-tab="${b.dataset.caseJump}"]`);if(tab)tab.click()}))}
function showToast(message){toast.textContent=message+' — در Prototype داده‌ای ذخیره نمی‌شود.';toast.classList.add('show');clearTimeout(showToast.t);showToast.t=setTimeout(()=>toast.classList.remove('show'),3200)}
document.addEventListener('click',e=>{const demo=e.target.closest('[data-demo]');if(demo){e.preventDefault();showToast(demo.dataset.demo)}});document.querySelector('#menuToggle').addEventListener('click',()=>document.querySelector('#sidebar').classList.toggle('open'));document.querySelector('.global-search input').addEventListener('keydown',e=>{if(e.key==='Enter')showToast('جست‌وجوی گروه‌بندی‌شده پرونده، کالا، شرکت و سند')});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();document.querySelector('.global-search input').focus()}});window.addEventListener('hashchange',render);render();
